    def bands(n, active):
        out = []
        i = 0
        while i < n:
            if not active(i):
                i += 1
                continue
            a = i
            while i < n and active(i):
                i += 1
            if i - a >= 3:
                out.append((a, i - 1))
        return out

    rb = bands(h, lambda r: any(grid[r][c] != 0 for c in range(w)))
    cb = bands(w, lambda c: any(grid[r][c] != 0 for r in range(h)))

    # Ignore clipped slivers at the grid boundary.
    rb = [(a, b) for a, b in rb if b - a + 1 >= 3]
    cb = [(a, b) for a, b in cb if b - a + 1 >= 3]
    if not rb or not cb:
        return [row[:] for row in grid]

    centers_r = [(a + b) // 2 for a, b in rb]
    centers_c = [(a + b) // 2 for a, b in cb]
    vals = [[grid[r][c] for c in centers_c] for r in centers_r]

    from collections import Counter
    base = Counter(v for row in vals for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    def paint_segment(r1, c1, r2, c2, color):
        if r1 == r2:
            for c in range(min(c1, c2) + 1, max(c1, c2)):
                if out[r1][c] == 0:
                    out[r1][c] = color
        else:
            for r in range(min(r1, r2) + 1, max(r1, r2)):
                if out[r][c1] == 0:
                    out[r][c1] = color

    # Connect equal, non-background markers in each tile row and column.
    for i, r in enumerate(centers_r):
        for j in range(len(centers_c)):
            color = vals[i][j]
            if color == base:
                continue
            for k in range(j + 1, len(centers_c)):
                if vals[i][k] == color:
                    width = max(1, min(rb[i][1] - rb[i][0] - 1,
                                       cb[j][1] - cb[j][0] - 1))
                    for d in range(width):
                        rr = r - (width - 1) // 2 + d
                        paint_segment(rr, centers_c[j], rr, centers_c[k], color)

    for j, c in enumerate(centers_c):
        for i in range(len(centers_r)):
            color = vals[i][j]
            if color == base:
                continue
            for k in range(i + 1, len(centers_r)):
                if vals[k][j] == color:
